  if (a.length === 1) {
    // single digit range
    return charClass(a,b)
  }
  if (a === b) return a;
  // If first digits equal:
  if (a[0] === b[0]) {
    return a[0] + sameLengthRegex(a.slice(1), b.slice(1));
  }
  // If a[0]+1 == b[0] ... split
  let parts = [];
  // lower part: a[0] followed by regex for a[1..] to 9...9
  // middle part: digits a[0]+1 .. b[0]-1 followed by \d{remaining}
  // upper part: b[0] followed by 0..0 to b[1..]
  if (remaining > 0) {
    parts.push(a[0] + sameLengthRegex(a.slice(1), '9'.repeat(rem)));
    let lo = +a[0]+1, hi = +b[0]-1;
    if (lo <= hi) parts.push(charClass(lo,hi) + '\\d{' + rem + '}');
    parts.push(b[0] + sameLengthRegex('0'.repeat(rem), b.slice(1)));
