function charClass(a, b) {
  if (a === b) return String(a);
  if (a === 0 && b === 9) return '\\d';
  return `[${a}-${b}]`;
}

// regex for fixed-length numeric strings between a and b (inclusive), same length
function fixedLength(a, b) {
  const rem = a.length - 1;
  if (rem === 0) return charClass(Number(a), Number(b));
  if (a === b) return a;
  if (a[0] === b[0]) {
    return a[0] + fixedLength(a.slice(1), b.slice(1));
  }
  const parts = [];
  // lower: first digit = a[0], rest from a[1..] to 99..9
  parts.push(a[0] + fixedLength(a.slice(1), '9'.repeat(rem)));
  const lo = Number(a[0]) + 1;
  const hi = Number(b[0]) - 1;
  if (lo <= hi) {
    parts.push((lo === hi ? String(lo) : charClass(lo, hi)) + `\\d{${rem}}`);
  }
  // upper: first digit = b[0], rest from 00..0 to b[1..]
  parts.push(b[0] + fixedLength('0'.repeat(rem), b.slice(1)));
  return `(?:${parts.join('|')})`;
