export function rangeToRegex(input, maxArg) {
  let min, max;
  if (typeof input === 'string') {
    const m = input.trim().match(/^(-?\d+)\s*-\s*(-?\d+)$/);
    if (!m) throw new TypeError(...);
    min = Number(m[1]); max = Number(m[2]);
  } else {
    min = Number(input); max = Number(maxArg);
  }
  if (!Number.isInteger(min) || !Number.isInteger(max)) throw ...
  if (min > max) [min,max]=[max,min];
  if (min === 0 && max === 0) return /^(?:0)$/; // or /^0$/
  const parts = [];
  if (min < 0) {
    const negMax = Math.min(max, -1);
    const upperAbs = Math.min(-min, ...); 
    // negative numbers from min to min(max,-1): as '-' + positive range [1, abs]
    const lowAbs = min === negMax ? -negMax : 1; 
    // actually negative range [min, negMax] where negMax<=-1 corresponds to abs range [-negMax, -min]
    parts.push('-' + positiveRange(-negMax, -min));
  }
  const posMin = Math.max(min, 0);
  if (max >= posMin) {
    parts.push(positiveRange(posMin, max));
  }
  const body = parts.length === 1 ? parts[0] : `(?:${parts.join('|')})`;
  return new RegExp(`^(?:${body})$`);
}
