{
  "name": "range-to-regex",
  "version": "0.1.0",
  "description": "Convert a numeric range like '1-100' into a regular expression that matches any number in that range.",
  "type": "module",
  "main": "src/index.js",
  "exports": {
    ".": "./src/index.js"
  },
  "bin": {
    "range-to-regex": "bin/cli.js"
  },
  "files": [
    "src",
    "bin"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

function charClass(low, high) {
  if (low === high) return String(low);
  if (low === 0 && high === 9) return "\\d";
  return `[${low}-${high}]`;
}

function fixedLength(low, high) {
  const remaining = low.length - 1;
  if (remaining === 0) return charClass(Number(low), Number(high));
  if (low === high) return low;

  if (low[0] === high[0]) {
    return low[0] + fixedLength(low.slice(1), high.slice(1));
  }

  const parts = [
    low[0] + fixedLength(low.slice(1), "9".repeat(remaining)),
  ];

  const midLow = Number(low[0]) + 1;
  const midHigh = Number(high[0]) - 1;
  if (midLow <= midHigh) {
    parts.push(charClass(midLow, midHigh) + `\\d{${remaining}}`);
  }

  parts.push(high[0] + fixedLength("0".repeat(remaining), high.slice(1)));

  return `(?:${parts.join("|")})`;
}

function positiveRange(min, max) {
  const parts = [];
  const minLength = String(min).length;
  const maxLength = String(max).length;

  for (let length = minLength; length <= maxLength; length += 1) {
    const low = length === 1 ? Math.max(min, 0) : Math.max(min, 10 ** (length - 1));
    const high = Math.min(max, 10 ** length - 1);
    if (low > high) continue;
    parts.push(fixedLength(String(low), String(high)));
  }

  return parts.length === 1 ? parts[0] : `(?:${parts.join("|")})`;
}

export function rangeToRegexSource(input, maxArg) {
  let min;
  let max;

  if (typeof input === "string") {
    const match = input.trim().match(/^(-?\d+)\s*-\s*(-?\d+)$/);
    if (!match) {
      throw new TypeError(
        `Invalid range "${input}". Expected a string like "1-100".`,
      );
    }
    min = Number(match[1]);
    max = Number(match[2]);
  } else {
    min = Number(input);
    max = Number(maxArg);
  }

  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError("Range bounds must be integers.");
  }

  if (min > max) [min, max] = [max, min];

  const parts = [];

  if (min < 0) {
    const negativeHigh = Math.min(max, -1);
    parts.push("-" + positiveRange(-negativeHigh, -min));
  }

  const nonNegativeLow = Math.max(min, 0);
  if (max >= nonNegativeLow) {
    parts.push(positiveRange(nonNegativeLow, max));
  }

  return parts.length === 1 ? parts[0] : `(?:${parts.join("|")})`;
}

export function rangeToRegex(input, maxArg) {
  return new RegExp(`^(?:${rangeToRegexSource(input, maxArg)})$`);
}

export default rangeToRegex;

#!/usr/bin/env node
import { rangeToRegex, rangeToRegexSource } from "../src/index.js";

const args = process.argv.slice(2);

if (args.length === 0 || args.includes("-h") || args.includes("--help")) {
  console.log("Usage: range-to-regex <range> [--source]");
  console.log("  range-to-regex 1-100");
  console.log("  range-to-regex --source 1-100");
  process.exit(args.length === 0 ? 1 : 0);
}

const sourceOnly = args.includes("--source");
const range = args.find((arg) => !arg.startsWith("--"));

try {
  if (sourceOnly) {
    console.log(rangeToRegexSource(range));
  } else {
    console.log(rangeToRegex(range));
  }
} catch (error) {
  console.error(error.message);
  process.exit(1);
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { rangeToRegex, rangeToRegexSource } from "../src/index.js";

function matches(re, value) {
  return new RegExp(re.source).test(String(value));
}

test("matches every integer in a range and nothing outside", () => {
  const cases = [
    [1, 100],
    [0, 9],
    [0, 10],
    [5, 12],
    [123, 4599],
    [-50, 50],
    [-100, -1],
    [-300, -150],
    [0, 0],
    [42, 42],
    [999, 1000],
    [1, 999999],
  ];

  for (const [min, max] of cases) {
    const re = rangeToRegex(`${min}-${max}`);

    const inside = new Set([min, max, Math.trunc((min + max) / 2)]);
    for (const n of inside) {
      assert.ok(matches(re, n), `${n} should match range ${min}-${max}`);
    }

    for (const n of [min - 1, max + 1, max + 1000, min - 1000]) {
      assert.ok(!matches(re, n), `${n} should not match range ${min}-${max}`);
    }
  }
});

test("rejects leading zeros and partial matches", () => {
  const re = rangeToRegex("1-100");
  assert.ok(matches(re, "1"));
  assert.ok(matches(re, "100"));
  assert.ok(!matches(re, "01"));
  assert.ok(!matches(re, "1000"));
  assert.ok(!matches(re, "1abc"));
  assert.ok(!matches(re, "abc"));
});

test("accepts (min, max) arguments and whitespace", () => {
  assert.equal(rangeToRegex(1, 100).source, rangeToRegex("1-100").source);
  assert.equal(rangeToRegex(" 1 - 100 ").source, rangeToRegex("1-100").source);
});

test("swaps reversed bounds", () => {
  assert.equal(rangeToRegex("100-1").source, rangeToRegex("1-100").source);
});

test("exposes the raw pattern source", () => {
  assert.equal(rangeToRegexSource(1, 100), rangeToRegex("1-100").source.slice(3, -2));
});

test("rejects malformed input", () => {
  assert.throws(() => rangeToRegex("nope"), TypeError);
  assert.throws(() => rangeToRegex("1-"), TypeError);
  assert.throws(() => rangeToRegex("a-b"), TypeError);
});

